#pragma once
// Charger timezone for gateway-side local-time math (#81).
//
// The charger reports its timezone as an IANA name (g_tzn). Schedules store
// `start` in UTC but `days` as the charger's LOCAL weekday, so anything that
// matches a schedule against a weekday needs the charger's local time.
// wb_tz maps the IANA name to a POSIX TZ string (bundled table generated by
// scripts/gen_tz_table.py), applies it with setenv("TZ") / tzset(), and
// converts with localtime_r(). An unknown name (or none yet) falls back to
// UTC, i.e. the pre-#81 behaviour.
#include <time.h>

namespace wb_tz {

// Create the mutex. Call once from setup() before any task uses wb_tz.
void begin();

// Set the charger's IANA timezone (e.g. "Europe/Madrid"). Returns true if
// the name is in the table; false leaves the gateway on UTC. Cheap when the
// name hasn't changed, so it can be called on every settings poll.
bool setZone(const char* iana);

// Charger-local broken-down time for `t` (UTC when no zone is known).
// Thread-safe.
void localTime(time_t t, struct tm* out);

}  // namespace wb_tz
